import itertools
lines = open('deploy.log').read().split('\n')
req = [lines[0]] + [l for l in lines if l.startswith('ERROR')]
def common_positions(a, b):
    res = []
    for i in range(len(a)):
        for j in range(len(b)):
            k = 0
            while i+k < len(a) and j+k < len(b) and a[i+k] == b[j+k]:
                k += 1
            res.append((i, j, k))
    return res
def merge_any(s, l):
    # splice l into s at best common substring; also consider plain append
    best = s + l
    best_len = len(best)
    for (i, j, k) in common_positions(s, l):
        if k < 2: continue
        cand = s[:i] + l + s[i+k:]
        if len(cand) < best_len:
            best, best_len = cand, len(cand)
    return best
best = None
for perm in itertools.permutations(range(len(req))):
    s = req[perm[0]]
    for i in perm[1:]:
        s = merge_any(s, req[i])
    if best is None or len(s) < len(best):
        best = s
print(len(best))
print(repr(best))
for r in req:
    print(r in best, r[:40])
